/**  Reading the file failed. */
"io" | 
/**  The probe result cannot be registered (for example a zero duration). */
"invalid";

/**  One imported file. */
export type ImportedMedia = {
	/**  The path as requested. */
	path: string,
	/**  The asset; an existing one if the same content was imported before. */
	media_id: MediaId,
	/**  What the asset is. */
	kind: MediaKind,
	/**  `true` when the content was already in the project and nothing was added. */
	duplicate: boolean,
};

/**  A broken document invariant: what [`Project::validate`] reports. */
export type Invariant = 
/**
 *  The document is not at the schema version this build edits (open it through
 *  `open`/`migrate_to_current`, which migrate older documents).
 */
{ invariant: "schema_version"; 
/**  The document's `meta.schema_version`. */
found: number; 
/**  `CURRENT_SCHEMA_VERSION`. */
expected: number } | 
/**  A map key differs from the ID inside the entity. */
{ invariant: "key_mismatch"; 
/**  The map (`/media`, `/sequences/<id>/tracks`, …). */
path: string; 
/**  The key. */
key: string; 
/**  The entity's own ID. */
id: string } | 
/**  A reference to an entity that does not exist. */
{ invariant: "dangling_reference"; 
/**  Where the reference is. */
path: string; 
/**  The kind of entity referred to. */
kind: EntityKind; 
/**  The missing ID. */
id: string } | 
/**  A media asset whose fields contradict its kind. */
{ invariant: "invalid_media"; 
/**  The media. */
media: MediaId; 
/**  What is wrong. */
reason: string } | 
/**  A sequence format (or the default format) outside the supported range. */
{ invariant: "invalid_format"; 
/**  The format. */
path: string; 
/**  What is wrong. */
reason: string } | 
/**  `track_order` is not exactly the keys of `tracks`. */
{ invariant: "track_order"; 
/**  The sequence. */
sequence: SequenceId; 
/**  What is wrong. */
reason: string } | 
/**  A clip whose media cannot play on its track (e.g. audio on a video track). */
{ invariant: "incompatible_media"; 
/**  The item. */
item: ItemId; 
/**  Its track. */
track: TrackId; 
/**  The track kind. */
track_kind: TrackKind; 
/**  The media. */
media: MediaId; 
/**  The media kind. */
media_kind: MediaKind } | 
/**
 *  An item with a non-positive duration, a negative start or source position, or an end
 *  past the largest representable time.
 */
{ invariant: "invalid_timing"; 
/**  The item. */
item: ItemId; 
/**  What is wrong. */
reason: string } | 
/**  A clip that reads past the end of its media (`source_in + duration > media duration`). */
{ invariant: "source_out_of_bounds"; 
/**  The item. */
item: ItemId; 
/**  The media. */
media: MediaId; 
/**  `source_in + duration`. */
source_end: Time; 
/**  The media duration. */
media_duration: Duration } | 
/**  Two items of one track overlap (arch §4.3: never). */
{ invariant: "overlap"; 
/**  The sequence. */
sequence: SequenceId; 
/**  The track. */
track: TrackId; 
/**  The earlier item. */
first: ItemId; 
/**  The item starting inside it. */
second: ItemId } | 
/**  Sequences that contain each other through compound clips (arch §4.3). */
{ invariant: "compound_cycle"; 
/**  The sequences on the cycle; the first is repeated at the end. */
cycle: SequenceId[] } | 
/**  A linked group with items in two sequences. */
{ invariant: "linked_group_spans_sequences"; 
/**  The group. */
group: GroupId; 
/**  One sequence. */
first: SequenceId; 
/**  Another sequence. */
second: SequenceId } | 
/**  A number that is not finite or outside its range (e.g. opacity above 1). */
{ invariant: "invalid_value"; 
/**  The value. */
path: string; 
/**  What is wrong. */
reason: string } | 
/**  Plugin data under a key that is not a namespace (arch §4.3). */
{ invariant: "custom_namespace"; 
/**  The custom map. */
path: string; 
/**  The key. */
key: string };

/**
 *  Anything placed on a track (arch §4.2). Schema v1 has only [`Clip`]; matching code outside
 *  this crate needs a wildcard arm for the kinds still to come.
 * 
 *  Serialized as the variant's object plus a `"kind"` tag (`{"kind": "clip", …}`).
 */
export type Item = 
/**  A media clip. */
{
	kind: "clip",
} & Clip;

/**
 *  Deletes items and their linked partners. Gaps stay (no ripple). All or nothing: if any
 *  affected track is locked the call fails with `Locked` and nothing is deleted. Unknown items
 *  are `NotFound`; repeated IDs are deleted once.
 */
export type ItemDelete = {
	/**  The items to delete, at least one. */
	items: ItemId[],
};

/**  Result of `item.delete`. */
export type ItemDeleteOutput = {
	/**  Every deleted item: the requested ones in request order, then their linked partners. */
	deleted: ItemId[],
};

/**
 *  Reads one item: the `timeline.get` item summary plus its track, source, audio and visual
 *  properties. `fields` limits the extra sections (`name`, `source`, `audio`, `visual`).
 */
export type ItemGet = {
	/**  The item. */
	item: ItemId,
	/**  Sections to include: any of `name`, `source`, `audio`, `visual` (default all). */
	fields?: string[] | null,
};

/**  Result of `item.get`. */
export type ItemGetOutput = {
	/**  The sequence holding the item. */
	sequence: SequenceId,
	/**  The track holding the item. */
	track: TrackId,
	/**  The same projection `timeline.get` returns at depth 2. */
	item: ItemSummary,
	/**  The display name, if it has one (unless `fields` leaves it out). */
	name?: string | null,
	/**  Media and source position (unless `fields` leaves it out). */
	source?: ItemSource | null,
	/**  Audio properties (unless `fields` leaves them out). */
	audio?: AudioProps | null,
	/**  Visual properties (unless `fields` leaves them out). */
	visual?: VisualProps | null,
	/**  The other items of the linked group, if any. */
	linked: ItemId[],
};

/**
 *  The ID of a timeline `Item`: `itm_…`.
 * 
 *  Serialized as a string, exported to TypeScript as `string`.
 */
export type ItemId = string & { readonly __brand: "ItemId" };

/**
 *  Moves an item to a new start, optionally onto another track of the same kind and sequence.
 *  The item's linked partners move by the same amount on their own tracks (`unlink: true`
 *  moves only this item and removes it from its group). Overlap is `Invalid{path:"/start"}`
 *  by default; `overlap: "new_track"` puts the item on a new track directly above the target.
 *  `Locked` if the source, the target or a partner's track is locked. `start` is snapped to
 *  the sequence's frame grid and must be `>= 0`.
 */
export type ItemMove = {
	/**  The item. */
	item: ItemId,
	/**  New timeline position of the item's first frame, `>= 0`. */
	start: TimeInput,
	/**  Target track of the same sequence and kind (default: stay on the current track). */
	to_track?: TrackId | null,
	/**  Move only this item and remove it from its linked group (default `false`). */
	unlink?: boolean | null,
	/**  Overlap handling (default `reject`). */
	overlap?: OverlapPolicy | null,
};

/**  Result of `item.move`. */
export type ItemMoveOutput = {
	/**  The moved items: the requested one first, then its linked partners. */
	items: MovedItem[],
	/**  Tracks created by `overlap: "new_track"`, in creation order. */
	created_tracks: TrackId[],
};

/**  Item properties to change: absent fields keep their value. */
export type ItemProps = {
	/**  Display name; an empty string clears it (the media name is shown again). */
	name: string | null,
	/**  Rendered and heard (`true`) or kept but skipped (`false`). */
	enabled: boolean | null,
	/**  Opacity `0.0..=1.0`. */
	opacity: number | null,
	/**  Clip gain in dB, `-144..=48` (0 = unchanged). */
	audio_gain: number | null,
	/**  Placement on the canvas (partial). */
	transform: TransformPatch | null,
};

/**
 *  Changes an item's name, enabled flag, opacity, clip gain or transform; absent fields keep
 *  their value and setting a value it already has is a no-op. `Locked` if the item's track is
 *  locked.
 */
export type ItemSetProps = {
	/**  The item. */
	item: ItemId,
	/**  The properties to change; at least one. */
	props: ItemProps,
};

/**  Result of `item.set_props`. */
export type ItemSetPropsOutput = {
	/**  The item. */
	item: ItemId,
	/**
	 *  The props whose value actually changed (`name`, `enabled`, `opacity`, `audio_gain`,
	 *  `transform.position`, ...); empty if everything was already as requested.
	 */
	changed: string[],
};

/**  Where a clip reads from. */
export type ItemSource = {
	/**  The media. */
	media: MediaId,
	/**  Position in the media of the clip's first frame. */
	source_in: Time,
};

/**  One item of a track (depth 2). */
export type ItemSummary = {
	/**  The item. */
	id: ItemId,
	/**  Item kind (`clip`). */
	kind: string,
	/**  Timeline position of the first frame. */
	start: Time,
	/**  Length on the timeline. */
	duration: Duration,
	/**  The media a clip plays. */
	media: MediaId | null,
	/**  The linked group, if any. */
	linked_group: GroupId | null,
	/**  Whether the item is rendered and heard. */
	enabled: boolean,
};

/**
 *  Cancels a background job. A queued job is cancelled at once; a running one stops within
 *  500 ms (`running` with `cancel_requested` until then; `job.wait` to see it end). Cancelling
 *  a finished job changes nothing. Returns the job's state.
 */
export type JobCancel = {
	/**  The job. */
	id: JobId,
};

/**
 *  The ID of a background job: `job_…` (a UUIDv7, so IDs sort by creation).
 * 
 *  Serialized as a string, exported to TypeScript as `string`.
 */
export type JobId = string & { readonly __brand: "JobId" };

/**
 *  A job as reported by `job.status`, `job.list`, `job.wait`, `job.cancel` and the
 *  `job.progress` event.
 */
export type JobInfo = {
	/**  The job. */
	id: JobId,
	/**  What kind of work it is. */
	kind: JobKind,
	/**  What it does, e.g. the analysis stage (`index`, `thumbnails`, `waveform`). */
	label: string,
	/**  The media asset it works on, if any. */
	media_id: MediaId | null,
	/**  Where it is in its lifecycle. */
	state: JobState,
	/**  How far it got. */
	progress: JobProgress,
	/**  Whether cancellation was requested; a running job stops when it next checks. */
	cancel_requested: boolean,
	/**  Why it failed, was skipped or was cancelled. */
	error: string | null,
};

/**  What kind of work a job does. The kind decides which [`Budget`] it runs under. */
export type JobKind = 
/**  Background analysis of an imported asset (index, thumbnails, waveform): decodes media. */
"analysis" | 
/**  Rendering and encoding a sequence to a file (WP-1E.03). */
"export";

/**
 *  Lists background jobs, newest first: unfinished ones and recently finished ones, optionally
 *  only those of one asset, state or kind.
 */
export type JobList = {
	/**  Only jobs working on this media asset. */
	media_id?: MediaId | null,
	/**  Only jobs in this state (e.g. `running`). */
	state?: JobState | null,
	/**  Only jobs of this kind. */
	kind?: JobKind | null,
	/**  Most jobs returned, `1..=500` (default 50). */
	limit?: number | null,
};

/**  Result of `job.list`. */
export type JobListOutput = {
	/**  The jobs, newest first. */
	jobs: JobInfo[],
	/**  How many jobs are unfinished (queued or running) in total, whatever the filter. */
	active: number,
};

/**  How far a job got. */
export type JobProgress = {
	/**  Done fraction, `0..=1` (1 once the job succeeded). */
	fraction: number | null,
	/**  What it is doing, for status lines. */
	message: string | null,
};

/**  Where a job is in its lifecycle. `succeeded`, `failed` and `cancelled` are final. */
export type JobState = 
/**  Waiting for the jobs it depends on or for a budget slot. */
"queued" | 
/**  Running. */
"running" | 
/**  Finished its work. */
"succeeded" | 
/**  Stopped with an error (see `error`), or skipped because a job it needs failed. */
"failed" | 
/**  Cancelled before or while running. */
"cancelled";

/**
 *  Gets a background job's state (`queued`, `running`, `succeeded`, `failed`, `cancelled`),
 *  progress and error. Finished jobs are remembered for a while (the last few hundred), then
 *  `NotFound`.
 */
export type JobStatus = {
	/**  The job (from `media.import`'s `job_ids`, `export.start`, …). */
	id: JobId,
};

/**
 *  Waits for a background job to finish, at most `timeout_ms` (default 30 s, capped at 60 s),
 *  and returns its state: at once for a finished job, as soon as it finishes, or still
 *  `queued`/`running` with its progress when the time is up (call again to keep waiting).
 */
export type JobWait = {
	/**  The job. */
	job_id: JobId,
	/**
	 *  How long to wait in milliseconds (default 30000; values above 60000 are capped; 0
	 *  returns the current state).
	 */
	timeout_ms?: number | null,
};

/**
 *  TypeScript shape of any JSON value (numbers are plain `number`s). Only its type
 *  definition is used.
 */
export type JsonValue = null | boolean | number | string | JsonValue[] | { [key in string]: JsonValue };

/**
 *  What `edit.undo{*}` and `edit.redo{*}` (anyone's latest change) would do: the shared view the
 *  editor's Undo and Redo buttons use (ADR-0019).
 */
export type LatestStacks = {
	/**  Entries `*` can undo, over every actor (0 disables Undo). */
	undo_depth: number,
	/**  Entries `*` can redo, over every actor (0 disables Redo). */
	redo_depth: number,
	/**  What `edit.undo{*}` would revert next. */
	next_undo: LatestTop | null,
	/**  What `edit.redo{*}` would re-apply next. */
	next_redo: LatestTop | null,
};

/**  The next entry `edit.undo{*}` / `edit.redo{*}` would move, and whose it is. */
export type LatestTop = {
	/**  Its transaction. */
	tx_id: TxId,
	/**  Its label ("Undo <label>"). */
	label: string,
	/**  For undo, the actor that made the change; for redo, the actor that undid it. */
	actor: Actor,
};

/**  Every checkpoint, oldest first. */
export type ListCheckpoints = Record<string, never>;

/**
 *  Lists the open transactions (oldest first) and the items each soft-locks: a `gesture` or
 *  `proposal` locks every item it touched for other actors until it closes; a `batch` locks
 *  nothing. Gestures carry their idle deadline (`expires_at`); `mine` marks your connection's.
 */
export type ListLocks = Record<string, never>;

/**  What `edit.locks` returns. */
export type LockList = {
	/**  Every open transaction, oldest first. */
	transactions: TxLocks[],
	/**  The live revision. */
	rev: Rev,
	/**  The committed revision. */
	committed_rev: Rev,
};

/**
 *  YUV matrix coefficients (H.273).
 * 
 *  Serialized as its name (e.g. `"bt709"`); unknown names are kept as `Other`.
 */
export type MatrixCoefficients = string;

/**
 *  `media.analysis_failed`: a background analysis stage failed on an asset. The asset stays
 *  usable; what the stage produces (thumbnails, waveform, …) may be missing.
 */
export type MediaAnalysisFailed = {
	/**  The asset. */
	media_id: MediaId,
	/**  The stage (`index`, `thumbnails`, `waveform`): the job's label. */
	stage: string,
	/**  The failed job (`job.status` shows it). */
	job_id: JobId,
	/**  What went wrong (the job's error). */
	error: string,
};

/**
 *  Media imported into (or generated for) a project, referenced by path and content hash
 *  (arch §17), or a sequence of this project used as a compound clip.
 */
export type MediaAsset = {
	/**  The media ID (also its key in `Project::media`). */
	id: MediaId,
	/**  What the media is. */
	kind: MediaKind,
	/**  Absolute path of the file when it was last found (file kinds only). */
	path_abs: string | null,
	/**  Path relative to the project folder, used for relinking moved projects (file kinds only). */
	path_rel: string | null,
	/**  Content hash used to relink and to key caches (file kinds only). */
	content_hash: string | null,
	/**  The referenced sequence (`sequence_ref` only). */
	sequence: SequenceId | null,
	/**  Probe results. */
	probe: ProbeInfo,
	/**  Plugin data (arch §4.3). */
	custom: { [key in string]: JsonValue },
} & { [key in string]: unknown };

/**
 *  Returns what this engine's media backend can decode and encode: software codecs with their
 *  implementations, the hardware encoders in the order `export.start{hw: "auto"}` tries them,
 *  and the hardware decode paths. `available` is false when the engine has no media backend.
 */
export type MediaCapabilities = Record<string, never>;

/**  Result of `media.capabilities`. */
export type MediaCapabilitiesOutput = {
	/**  Whether the engine has a media backend at all. */
	available: boolean,
	/**  Software codecs, sorted by name. */
	codecs: CodecInfo[],
	/**  Hardware encoders that passed a test encode, in the order `auto` tries them. */
	hw_encode: HwCodecInfo[],
	/**  Hardware decode paths verified on this machine. */
	hw_decode: HwCodecInfo[],
};

/**
 *  The ID of a `MediaAsset`: `med_…`.
 * 
 *  Serialized as a string, exported to TypeScript as `string`.
 */
export type MediaId = string & { readonly __brand: "MediaId" };

/**
 *  Imports media files and returns their `media_ids` at once (arch §7, R21). Each file is
 *  probed synchronously (up to 4 at a time, 5 s each by default) and every readable one is
 *  registered in one transaction (one undo step); files that are missing, unsupported, corrupt
 *  or too slow to probe are listed in `failed` and get no asset. Files whose content is
 *  already in the project are returned as duplicates. Background analysis (frame index,
 *  thumbnails, waveform) then runs as jobs whose ids are returned in `job_ids`. Agents and
 *  headless callers may only import from the project folder and user-approved folders; any
 *  other path fails the call with `Invalid` at `/paths/<i>`.
 */
export type MediaImport = {
	/**  Absolute paths of the files (1..=256, no repeats). */
	paths: string[],
};

/**  Result of `media.import`. */
export type MediaImportOutput = {
	/**  One entry per imported path, in request order. */
	media: ImportedMedia[],
	/**  The assets of `media`, in the same order (duplicates name the existing asset). */
	media_ids: MediaId[],
	/**  The paths that could not be imported, in request order. */
	failed: ImportFailure[],
	/**
	 *  Background analysis jobs queued for the new assets (wait with `job.wait`); empty when
	 *  no analysis stage is installed.
	 */
	job_ids: JobId[],
};

/**  `media.indexed`: the asset's frame index is ready. */
export type MediaIndexed = {
	/**  The asset. */
	media_id: MediaId,
};

/**  What a [`MediaAsset`] is. */
export type MediaKind = 
/**  A video file (may also carry audio). */
"video" | 
/**  An audio-only file. */
"audio" | 
/**  A still image (no duration). */
"image" | 
/**  Another sequence of this project, used as a compound clip (arch §4.3). */
"sequence_ref";

/**  Lists the media of the project, ordered by ID, one page at a time. */
export type MediaList = {
	/**  Page size, `1..=500` (default 50). */
	limit?: number | null,
	/**  `next_cursor` of the previous page; the page starts after this ID. */
	cursor?: MediaId | null,
};

/**  Result of `media.list`. */
export type MediaListOutput = {
	/**  The page, ordered by ID. */
	media: MediaSummary[],
	/**  Pass as `cursor` to get the next page; absent on the last page. */
	next_cursor: MediaId | null,
	/**  Number of assets in the project. */
	total: number,
};

/**
 *  Registers a probed media file. Internal plumbing of `media.import` and the import job
 *  (WP-1D.07): the kind (video, audio or image) derives from the probe streams. If an asset
 *  with the same `content_hash` already exists it is returned unchanged (`created: false`).
 */
export type MediaRegister = {
	/**  ID for the new asset; minted by the engine when absent. Must not exist yet. */
	media_id?: MediaId | null,
	/**  Absolute path of the file. */
	path: string,
	/**  What probing found. */
	probe: ProbeInfo,
	/**  Content hash used to relink and deduplicate (non-empty, no whitespace). */
	content_hash: string,
};

/**  Result of `media.register`. */
export type MediaRegistered = {
	/**  The asset: the new one, or the existing one with the same content hash. */
	media_id: MediaId,
	/**  What the asset is. */
	kind: MediaKind,
	/**  `false` when an asset with the same content hash already existed and nothing changed. */
	created: boolean,
};

/**
 *  Removes a media asset from the project (the file on disk is untouched). Fails with
 *  `Invalid` while any clip uses it; delete those clips first.
 */
export type MediaRemove = {
	/**  The asset to remove. */
	id: MediaId,
};

/**  Result of `media.remove`. */
export type MediaRemoveOutput = {
	/**  The removed asset. */
	media_id: MediaId,
};

/**  Summary of one media asset. */
export type MediaSummary = {
	/**  The asset. */
	id: MediaId,
	/**  What it is. */
	kind: MediaKind,
	/**  Absolute path when it was last found (file kinds). */
	path: string | null,
	/**  Playable length, if known. */
	duration: Duration | null,
	/**  Whether it has pictures. */
	has_video: boolean,
	/**  Whether it has sound. */
	has_audio: boolean,
};

/**  Where one item ended up. */
export type MovedItem = {
	/**  The item. */
	item: ItemId,
	/**  The track it is on now. */
	track: TrackId,
	/**  Its new start. */
	start: Time,
};

/**  What to do when the clip would overlap another clip on the target track. */
export type OverlapPolicy = 
/**  Fail with `Invalid{path:"/at"}` (default). */
"reject" | 
/**  Create a new track of the same kind directly above the target and insert there. */
"new_track";

/**  An ordered list of [`PatchOp`]s, applied first to last. Serialized as a JSON array. */
export type Patch = PatchOp[];

/**  Why the live document changed. */
export type PatchCause = 
/**  A command committed in its own implicit transaction. */
"command" | 
/**  A command inside an open gesture or proposal (live, not committed yet). */
"live" | 
/**
 *  An open transaction committed. For a gesture or proposal the document already showed
 *  its changes, so `ops` is usually empty; for a batch it carries the batch's changes.
 */
"commit" | 
/**
 *  An open transaction was cancelled, rolled back or expired; `ops` undoes its live
 *  changes.
 */
"rollback" | 
/**  `edit.undo` reverted a history entry (`actor` is who undid it). */
"undo" | 
/**  `edit.redo` re-applied a history entry (`actor` is who redid it). */
"redo" | 
/**  `edit.restore` brought the document back to a checkpoint. */
"restore";

/**  One invertible edit of the project document. */
export type PatchOp = 
/**  Adds `value` at `path` (an absent object key, or an array index `0..=len`). */
{ op: "add"; 
/**  Where. */
path: string; 
/**  What. */
value: PatchValue } | 
/**  Removes the value at `path`, which must equal `old`. */
{ op: "remove"; 
/**  Where. */
path: string; 
/**  The value being removed (the preimage). */
old: PatchValue } | 
/**  Replaces the value at `path`, which must equal `old`, with `value`. */
{ op: "replace"; 
/**  Where. */
path: string; 
/**  The value being replaced (the preimage). */
old: PatchValue; 
/**  The new value. */
value: PatchValue } | 
/**  Moves the value at `from` to `path` (e.g. an item to another track). */
{ op: "move"; 
/**  Source. */
from: string; 
/**  Destination (absent after the removal at `from`). */
path: string };

/**
 *  TypeScript shape of a patch value: any JSON value, with numbers as plain `number`s (specta
 *  refuses `serde_json::Value`'s 64-bit integers). Only its type definition is used.
 */
export type PatchValue = null | boolean | number | string | PatchValue[] | { [key in string]: PatchValue };

/**  Preview resolution (arch §8 quality ladder). */
export type PreviewQuality = 
/**  Full resolution. */
"full" | 
/**  Half resolution. */
"half" | 
/**  Quarter resolution. */
"quarter";

/**  What the media backend found in a file (WP-1D.02 fills it). */
export type ProbeInfo = {
	/**  Streams in container order. */
	streams: StreamInfo[],
	/**  Playable length, if known (images have none). */
	duration: Duration | null,
	/**  Frame rate of the main video stream, if constant or nominal. */
	fps: FrameRate | null,
	/**  Variable frame rate: times map through the frame index, never through `fps` (arch §4.1). */
	vfr: boolean,
	/**  Display rotation in degrees clockwise: 0, 90, 180 or 270. */
	rotation: number,
	/**  Color tags of the main video stream. */
	color: ColorTags,
	/**  Main audio stream format, if any. */
	audio: AudioInfo | null,
} & { [key in string]: unknown };

/**
 *  The project document: everything saved in `<Name>.cutweave` (arch §17).
 * 
 *  Entities are addressed by ID, never by index (arch §4.3). All collections are persistent
 *  (`imbl`), so `clone()` is O(1) and snapshots share structure (ADR-0005). Mutate only through
 *  commands (`cutweave-ops`); readers get immutable snapshots.
 * 
 *  The JSON form has a stable layout (fields in declaration order, maps sorted by key), so
 *  saved files diff cleanly.
 */
export type Project = {
	/**  Document metadata. */
	meta: ProjectMeta,
	/**  Project-wide settings. */
	settings: ProjectSettings,
	/**  Media, keyed by ID. */
	media: { [key in MediaId]: MediaAsset },
	/**  Sequences, keyed by ID. */
	sequences: { [key in SequenceId]: Sequence },
	/**  Plugin data (arch §4.3). */
	custom: { [key in string]: JsonValue },
} & { [key in string]: unknown };

/**
 *  Closes the open project (releasing its lock) and starts an untitled document. With
 *  `save: true` the committed state is saved first; with `save: false` nothing is saved (the
 *  unsaved work stays in the journal and is offered on the next open); by default it is saved
 *  when autosave is on. A failed save keeps the project open. Every client must resync.
 */
export type ProjectClose = {
	/**  Save before closing (`true`), never (`false`), or as autosave would (absent). */
	save?: boolean | null,
};

/**  Result of `project.close`. */
export type ProjectCloseOutput = {
	/**  The document path of the project that was closed (absent if none was open). */
	closed: string | null,
	/**  The session now (an untitled document). */
	project: ProjectStatus,
};

/**  `project.closed`. */
export type ProjectClosed = {
	/**  The document path of the project that was closed. */
	path: string,
};

/**  Payload of `project.dirty`. */
export type ProjectDirty = {
	/**  Whether the committed revision differs from the last saved one. */
	dirty: boolean,
};

/**
 *  Discards the unsaved work a crashed session left in the journal and continues from the
 *  saved document (the discarded journal is kept in `.cutweave/backups/`). Every client must
 *  resync.
 */
export type ProjectDiscardRecovery = Record<string, never>;

/**  Returns the project name, format, media count and a summary of each sequence. */
export type ProjectInfo = Record<string, never>;

/**  Result of `project.info`. */
export type ProjectInfoOutput = {
	/**  Project name. */
	name: string,
	/**  Document schema version. */
	schema_version: number,
	/**  Creation time (RFC 3339 UTC), if recorded. */
	created: string | null,
	/**  Format of new sequences. */
	default_format: SequenceFormat,
	/**  Number of media assets. */
	media_count: number,
	/**  The sequences, ordered by ID. */
	sequences: SequenceBrief[],
};

/**  Document metadata. */
export type ProjectMeta = {
	/**
	 *  Version of the document format (`CURRENT_SCHEMA_VERSION` when saved by this build).
	 *  Older documents are migrated on open; newer ones open read-only (arch §4.3).
	 */
	schema_version: number,
	/**  Project name. */
	name: string,
	/**
	 *  When the project was created (RFC 3339 UTC, e.g. `2026-11-22T10:00:00Z`), set by the
	 *  engine (frozen under `--deterministic-ids`).
	 */
	created: string | null,
	/**  Version of the Cutweave build that last saved the document. */
	app_version: string | null,
} & { [key in string]: unknown };

/**
 *  Initializes an empty project: sets the project name and default format and creates one
 *  sequence with a video track `V1` on top of an audio track `A1`. Fails with `Invalid` if the
 *  project already has media or sequences.
 */
export type ProjectNew = {
	/**  Project name (1..=200 characters). */
	name: string,
	/**  Format of the first sequence; also the default for new sequences. */
	format?: FormatSpec | null,
};

/**  Result of `project.new`. */
export type ProjectNewOutput = {
	/**  The created sequence. */
	sequence: SequenceId,
	/**  Its video track `V1`. */
	video_track: TrackId,
	/**  Its audio track `A1`. */
	audio_track: TrackId,
};

/**
 *  Opens a project (its folder or its `.cutweave` file), closing the current one first (saved
 *  when autosave is on, as `project.close` does). A project open in another Cutweave process
 *  fails with `Invalid` at `/path` and leaves the current project open. Unsaved work from a
 *  crashed session is reported in `project.recovery`; edits are refused until
 *  `project.recover` or `project.discard_recovery`. Every client must resync (`doc.reset`).
 *  Agents and headless callers may only open projects inside the open project's folder and
 *  the folders the user approved (`Invalid` at `/path` otherwise).
 */
export type ProjectOpen = {
	/**  Absolute path of the project folder or of its `.cutweave` document. */
	path: string,
};

/**  Result of `project.open`. */
export type ProjectOpenOutput = {
	/**  The session now. */
	project: ProjectStatus,
	/**  Media whose file was found at neither its absolute nor its project-relative path. */
	missing_media: MediaId[],
	/**  The schema version the document was migrated from, if it was. */
	migrated_from: number | null,
};

/**
 *  Restores the unsaved work a crashed session left in the journal (`project.recovery_available`):
 *  replays it onto the saved document, with undo history, and enables editing. The restored
 *  changes are unsaved until the next save or autosave. Every client must resync.
 */
export type ProjectRecover = Record<string, never>;

/**  Result of `project.recover` and `project.discard_recovery`. */
export type ProjectRecoverOutput = {
	/**  The session now. */
	project: ProjectStatus,
	/**  Transactions restored from the journal (0 after a discard). */
	applied: number,
	/**  Replay stopped at a damaged record (everything before it was restored). */
	damaged: boolean,
};

/**  Renames the project. */
export type ProjectRename = {
	/**  New project name (1..=200 characters). */
	name: string,
};

/**  Result of `project.rename`. */
export type ProjectRenameOutput = {
	/**  The name now in effect (trimmed). */
	name: string,
};

/**
 *  The desktop app reports that its window gained the focus. The engine records the time in
 *  its run-file (`focused_at`), so an agent that does not say which engine it means gets the
 *  one the person is looking at (`cutweave engines`, `docs/reference/launch-protocol.md`).
 *  UI credential only and never an MCP tool: it is the app applying its own state to the
 *  engine (ADR-0016). Not undoable, not journaled, never marks the project dirty.
 */
export type ProjectReportFocus = Record<string, never>;

/**  Result of `project.report_focus`. */
export type ProjectReportFocusOutput = {
	/**
	 *  When the engine recorded the focus, milliseconds since the Unix epoch (the run-file's
	 *  `focused_at`).
	 */
	focused_at: WallTime,
};

/**
 *  Saves the last committed state of the open project to its file (open gestures and
 *  proposals are not included). Fails with `Invalid` for an untitled document (use
 *  `project.save_as`) and `Unsupported` for a read-only project.
 */
export type ProjectSave = Record<string, never>;

/**
 *  Saves the document as a new project folder (created; it must not hold a project yet) and
 *  continues there; the old folder keeps its last save. A journaled project keeps its undo
 *  history; an untitled or read-only document is written and reopened (history restarts, every
 *  client resyncs on `doc.reset`). Agents and headless callers may only save inside the open
 *  project's folder and the folders the user approved (`Invalid` at `/path` otherwise).
 */
export type ProjectSaveAs = {
	/**  Absolute path of the new project folder; the document is `<folder>/<folder name>.cutweave`. */
	path: string,
};

/**  Result of `project.save` and `project.save_as`. */
export type ProjectSaveOutput = {
	/**  The project document written. */
	path: string,
	/**  The committed revision the project file now holds. */
	rev: Rev,
};

/**  Payload of `project.saved`. */
export type ProjectSaved = {
	/**  The committed revision that was written. */
	rev: Rev,
	/**  The project document path. */
	path: string,
};

/**
 *  Sets how this engine autosaves, for the open project and every project it opens later: the
 *  editor's own preference wins over the project's `settings.autosave` (arch §17). It takes
 *  effect at once, also for a project that is already dirty, and the 2 s idle save stays.
 *  Not undoable, not journaled and never marks the project dirty; it is not written to the
 *  project. An engine nobody sent it to keeps the project's own setting, then the defaults.
 */
export type ProjectSetAutosave = {
	/**  Save automatically (the idle save and the interval save), or not at all. */
	enabled: boolean,
	/**  Save at least this often, in seconds, while edits continue (1 to 86400). */
	interval_s: number,
	/**  Backups to keep in `.cutweave/backups/` (1 to 100). */
	keep_backups: number,
};

/**  Result of `project.set_autosave`: the preference now in force. */
export type ProjectSetAutosaveOutput = {
	/**  Whether autosave runs. */
	enabled: boolean,
	/**  The longest time, in seconds, a dirty project goes unsaved while edits continue. */
	interval_s: number,
	/**  Backups kept in the project's `.cutweave/backups/` folder. */
	keep_backups: number,
};

/**  Project-wide settings (arch §4.2 `settings`, v1 subset). */
export type ProjectSettings = {
	/**  Format of new sequences. */
	default_format: SequenceFormat,
} & { [key in string]: unknown };

/**  What the engine holds: the `project.*` commands return it and `project.opened` carries it. */
export type ProjectStatus = {
	/**  `no_project` (an untitled document) or `open`. */
	state: SessionState,
	/**  The project document (`.cutweave`) path; absent for an untitled document. */
	path: string | null,
	/**  The project name (from the document). */
	name: string,
	/**  The live document revision. */
	rev: Rev,
	/**
	 *  The committed revision last written to the project file; absent while untitled,
	 *  read-only or awaiting a recovery decision.
	 */
	saved_rev: Rev | null,
	/**  Whether committed changes are not in the project file yet. */
	dirty: boolean,
	/**  Why the project is read-only (edits are refused), if it is. */
	read_only: string | null,
	/**
	 *  Unsaved work from a previous session awaiting `project.recover` or
	 *  `project.discard_recovery` (edits are refused until then).
	 */
	recovery: RecoveryInfo | null,
};

/**  Unsaved work from a previous session (what a restore would bring back). */
export type RecoveryInfo = {
	/**  Transactions a restore would replay. */
	records: number,
	/**  The committed revision of the saved document. */
	base_rev: Rev,
	/**  The revision a restore reaches. */
	last_rev: Rev,
	/**  When the last of them was committed. */
	last_ts: WallTime,
	/**  The journal ends with a damaged record (replay stops there). */
	damaged: boolean,
};

/**
 *  Payload of `project.recovery_available`; also what a recovery dialog shows (what a restore
 *  would bring back).
 */
export type RecoveryPayload = {
	/**  Transactions a restore would replay. */
	records: number,
	/**  The committed revision of the saved document. */
	base_rev: Rev,
	/**  The revision a restore reaches. */
	last_rev: Rev,
	/**  When the last of those transactions was committed. */
	last_ts: WallTime,
	/**  The journal ends with a damaged record (replay stops there). */
	damaged: boolean,
};

/**
 *  Redoes the most recently undone change of an actor (default: yours). A new change by that
 *  actor clears its redo stack. Refused with `Conflict` when the same things changed since the
 *  undo.
 */
export type Redo = {
	/**  Whose change (see `edit.undo`). Default: the caller's own. */
	actor?: HistoryScope | null,
};

/**
 *  The idempotency key of a request (arch §5.1, ADR-0015): a client-generated UUIDv7, or one
 *  the engine generates for clients that omit it (CLI, MCP).
 * 
 *  A repeat within the dedup window returns the original result without re-applying. Any
 *  RFC 9562 UUID is accepted; text form is the usual lowercase `8-4-4-4-12` hex.
 */
export type RequestId = string & { readonly __brand: "RequestId" };

/**  What a [`CmdError::NotFound`] or [`CmdError::Locked`] refers to. */
export type ResourceKind = 
/**  A media asset (`med_…`). */
"media" | 
/**  A sequence (`seq_…`). */
"sequence" | 
/**  A track (`trk_…`). */
"track" | 
/**  A timeline item (`itm_…`). */
"item" | 
/**  A linked group (`grp_…`). */
"group" | 
/**  A registry entry: an unknown command or query name. */
"command" | 
/**  An open transaction (WP-1B.04). */
"transaction" | 
/**  A checkpoint (`cp_…` or its name, `edit.checkpoint`, WP-1B.04). */
"checkpoint" | 
/**  A background job (`job_…`, WP-1D.07). */
"job";

/**
 *  Brings the document back to a checkpoint as one new, undoable change by you (history is
 *  not truncated; `edit.undo` reverts the restore). Without `force`, refused with `Conflict`
 *  when it would also revert other actors' changes made since the checkpoint.
 */
export type Restore = {
	/**  The checkpoint: its id (`cp_<n>`) or name. */
	checkpoint: string,
	/**  Also revert other actors' changes made since the checkpoint. */
	force?: boolean,
};

/**  The result of `edit.restore`. */
export type Restored = {
	/**  The checkpoint. */
	checkpoint: CheckpointId,
	/**
	 *  The restoring transaction (undo it with `edit.undo`); `None` if the document already
	 *  equalled the checkpoint.
	 */
	tx: TxId | null,
	/**  The live revision afterwards. */
	rev: Rev,
	/**  The committed revision afterwards. */
	committed_rev: Rev,
	/**  Whose changes since the checkpoint it reverted. */
	reverted: RevertedChanges[],
	/**  It also reverted changes that are no longer in the history (authors unknown). */
	reverted_unknown: boolean,
};

/**
 *  Document revision: increases by one per committed transaction (WP-1B.03).
 * 
 *  A JSON integer on the wire and a TS `number`.
 */
export type Rev = number;

/**  Changes a checkpoint restore reverted, by actor. */
export type RevertedChanges = {
	/**  The actor. */
	actor: Actor,
	/**  Its transactions (since the checkpoint) whose changes were reverted, oldest first. */
	txs: TxId[],
};

/**  How a time that falls between two frame (or sample) boundaries is mapped to a unit index. */
export type Rounding = 
/**  The unit that contains the time (the latest boundary at or before it). */
"floor" | 
/**  The nearest boundary; exact halves round up (towards the later unit). */
"nearest";

/**
 *  An audio sample rate in Hz.
 * 
 *  Serialized as a JSON integer (`48000`).
 */
export type SampleRate = number;

/**  Which credentials may invoke an entry (arch §6, ADR-0016). */
export type Scope = 
/**  Any authenticated caller (UI, agents, plugins, the CLI, internal jobs). */
"any" | 
/**
 *  Only the UI credential (`ai.set_key`, approvals, allowlists, budgets, plugin grants).
 *  Enforced by the registry, so batches cannot bypass it.
 */
"ui";

/**  Timeline scroll offset in pixels, from the top-left of the timeline. */
export type Scroll = {
	/**  Horizontal offset, `>= 0`. */
	x: number | null,
	/**  Vertical offset, `>= 0`. */
	y: number | null,
};

/**  How `view.select` combines its IDs with the current selection. */
export type SelectMode = 
/**  The IDs become the selection. */
"replace" | 
/**  The IDs are appended (already selected ones keep their place). */
"add" | 
/**  The IDs are removed from the selection. */
"remove" | 
/**  Selected IDs are removed, the others appended. */
"toggle";

/**  One selected entity, by ID (never by index). */
export type SelectionRef = 
/**  A timeline item. */
{ kind: "item"; 
/**  The item. */
id: ItemId } | 
/**  A track. */
{ kind: "track"; 
/**  The track. */
id: TrackId } | 
/**  A media asset. */
{ kind: "media"; 
/**  The asset. */
id: MediaId } | 
/**  A sequence. */
{ kind: "sequence"; 
/**  The sequence. */
id: SequenceId };

/**
 *  A timeline (arch §4.2). A project may hold several (e.g. a long cut and its shorts); the v1
 *  UI shows one.
 */
export type Sequence = {
	/**  The sequence ID (also its key in `Project::sequences`). */
	id: SequenceId,
	/**  Display name. */
	name: string,
	/**  Canvas, rates and color. */
	format: SequenceFormat,
	/**  The tracks, keyed by ID. */
	tracks: { [key in TrackId]: Track },
	/**
	 *  Display order, top to bottom: every key of `tracks` exactly once. Upper video tracks
	 *  are composited over lower ones.
	 */
	track_order: TrackId[],
	/**  Plugin data (arch §4.3). */
	custom: { [key in string]: JsonValue },
} & { [key in string]: unknown };

/**  Summary of one sequence. */
export type SequenceBrief = {
	/**  The sequence. */
	id: SequenceId,
	/**  Its name. */
	name: string,
	/**  Its format. */
	format: SequenceFormat,
	/**  End of the last item on any track. */
	duration: Duration,
	/**  Number of video tracks. */
	video_tracks: number,
	/**  Number of audio tracks. */
	audio_tracks: number,
	/**  Number of items on all its tracks. */
	item_count: number,
};

/**  Canvas size, frame rate, audio rate and color of a sequence (arch §4.2 `format`). */
export type SequenceFormat = {
	/**  Canvas width in pixels. */
	width: number,
	/**  Canvas height in pixels. */
	height: number,
	/**  The edit grid: timecodes and `"f:N"` inputs resolve against it. */
	frame_rate: FrameRate,
	/**  The mix rate. */
	sample_rate: SampleRate,
	/**  Working color space. */
	color_space: ColorSpace,
	/**  Canvas color behind all tracks. */
	background: Color,
} & { [key in string]: unknown };

/**
 *  The ID of a `Sequence`: `seq_…`.
 * 
 *  Serialized as a string, exported to TypeScript as `string`.
 */
export type SequenceId = string & { readonly __brand: "SequenceId" };

/**  Where the session is in its lifecycle. */
export type SessionState = 
/**  An untitled document, not backed by a project folder. */
"no_project" | 
/**  A project folder is open. */
"open" | 
/**  The project is being closed (a swap or engine shutdown is under way). */
"closing";

/**  One split item. */
export type SplitPair = {
	/**  The left half (keeps the original item ID). */
	left: ItemId,
	/**  The right half (new ID). */
	right: ItemId,
};

/**  The next entry of a stack. */
export type StackTop = {
	/**  Its transaction. */
	tx_id: TxId,
	/**  Its label ("Undo <label>"). */
	label: string,
};

/**  One stream of a media file. */
export type StreamInfo = {
	/**  Index in the container. */
	index: number,
	/**  Stream kind. */
	kind: StreamKind,
	/**  Codec name (FFmpeg naming, e.g. `h264`, `aac`). */
	codec: string | null,
	/**  Codec profile (e.g. `High`, `Main 10`). */
	profile: string | null,
	/**  Coded width in pixels (video). */
	width: number | null,
	/**  Coded height in pixels (video). */
	height: number | null,
	/**  Pixel format (FFmpeg naming, e.g. `yuv420p10le`; video). */
	pixel_format: string | null,
	/**  Sample rate (audio). */
	sample_rate: SampleRate | null,
	/**  Channel count (audio). */
	channels: number | null,
	/**  Language tag (e.g. `eng`). */
	language: string | null,
} & { [key in string]: unknown };

/**  The kind of a container stream. */
export type StreamKind = 
/**  Pictures. */
"video" | 
/**  Sound. */
"audio" | 
/**  Subtitles or captions. */
"subtitle" | 
/**  Timed metadata or other data. */
"data" | 
/**  Attached files (fonts, cover art). */
"attachment";

/**
 *  A position on a timeline or in a source, in flicks (1/705,600,000 s).
 * 
 *  Always within ±[`MAX_SAFE_FLICKS`]; may be negative (relative offsets). Serialized as a JSON
 *  integer, exported to TypeScript as `number`.
 */
export type Time = number;

/**
 *  A time argument as clients send it (arch §4.1): flicks, seconds, a frame or a timecode.
 * 
 *  Integers and seconds resolve on their own; frames and timecodes need the frame rate of the
 *  sequence that owns the command's target ([`TimeInput::resolve`]). On the wire it is a JSON
 *  integer or one of the strings `"62.5s"`, `"123"`, `"f:1500"`, `"00:01:02:03"`,
 *  `"00:01:02;03"`; in TypeScript `number | string`.
 */
export type TimeInput = number | string;

/**
 *  Reads a sequence in layers: `depth` 0 is the sequence summary, 1 adds its tracks (summaries
 *  only, small), 2 adds every item. `fields` limits the sections returned (`name`, `format`,
 *  `duration`, `tracks`); the id and the counts are always included.
 */
export type TimelineGet = {
	/**  The sequence. */
	sequence: SequenceId,
	/**  Detail level `0..=2` (default 1). */
	depth?: number | null,
	/**  Sections to include: any of `name`, `format`, `duration`, `tracks` (default all). */
	fields?: string[] | null,
};

/**  Result of `timeline.get`. */
export type TimelineGetOutput = {
	/**  The sequence. */
	id: SequenceId,
	/**  Its name (unless `fields` leaves it out). */
	name?: string | null,
	/**  Its format (unless `fields` leaves it out). */
	format?: SequenceFormat | null,
	/**  End of the last item on any track (unless `fields` leaves it out). */
	duration?: Duration | null,
	/**  Number of tracks. */
	track_count: number,
	/**  Number of items on all tracks. */
	item_count: number,
	/**
	 *  The tracks in display order, top to bottom (depth >= 1, unless `fields` leaves them
	 *  out).
	 */
	tracks?: TrackSummary[] | null,
};

/**
 *  Inserts a media clip on a track at a time. `source_in` is the position in the media the clip
 *  starts from and `duration` its length (defaults: the start of the media and the rest of it;
 *  stills default to five seconds). Times accept flicks, `"1.5s"`, `"f:45"` and timecodes,
 *  resolved against the sequence's frame rate. `at` and `duration` snap to the frame grid
 *  (nearest frame, ties later; at least one frame) and the result states the values used;
 *  `source_in` is a position in the media and is not snapped, nor is a default duration
 *  (the rest of the media, or five seconds for a still). See the module docs for overlap and linked
 *  audio behaviour. Fails with `Locked` if the target track is locked.
 */
export type TimelineInsert = {
	/**  The sequence. */
	sequence: SequenceId,
	/**
	 *  The target track (of that sequence): a video track for pictures, an audio track for
	 *  sound.
	 */
	track: TrackId,
	/**  The media to place. */
	media: MediaId,
	/**  Timeline position of the clip's first frame, `>= 0` (snapped to the frame grid). */
	at: TimeInput,
	/**  Position in the media to start from (default 0). */
	source_in?: TimeInput | null,
	/**  Clip length, `> 0` (snapped to whole frames, at least one). */
	duration?: TimeInput | null,
	/**  Overlap handling (default `reject`). */
	overlap?: OverlapPolicy | null,
	/**  Also insert the audio of a video file as a linked clip (default `true`). */
	link?: boolean | null,
};

/**  Result of `timeline.insert`. */
export type TimelineInsertOutput = {
	/**  The start that was used, snapped to the frame grid. */
	at: Time,
	/**  The clip length that was used, a whole number of frames. */
	duration: Duration,
	/**  The inserted clips: the one on the target track first, then the linked audio clip. */
	clips: ItemId[],
	/**  The group shared by the clips when audio was linked. */
	linked_group: GroupId | null,
	/**  Tracks created by `overlap: "new_track"`, in creation order. */
	created_tracks: TrackId[],
};

/**  A track of a sequence (arch §4.2): items that never overlap (arch §4.3). */
export type Track = {
	/**  The track ID (also its key in `Sequence::tracks`). */
	id: TrackId,
	/**  What the track holds. */
	kind: TrackKind,
	/**  Display name. */
	name: string,
	/**  The items, keyed by ID. */
	items: { [key in ItemId]: Item },
	/**  Silenced (audio). */
	muted: boolean,
	/**  Not rendered (video). */
	hidden: boolean,
	/**  Commands that would change the track's items fail with `Locked`. */
	locked: boolean,
	/**  Solo (audio): when any track is solo, only solo tracks are heard. */
	solo: boolean,
	/**  Magnetic main track: ripple-by-default editing (arch §4.3; behaviour in P2). */
	magnetic: boolean,
	/**  Track gain in decibels (0.0 = unchanged). */
	gain: number,
	/**  Plugin data (arch §4.3). */
	custom: { [key in string]: JsonValue },
} & { [key in string]: unknown };

/**
 *  Adds an empty track to a sequence. New video tracks go on top of the stack, new audio
 *  tracks at the bottom, unless `index` says otherwise.
 */
export type TrackAdd = {
	/**  The sequence. */
	sequence: SequenceId,
	/**  `video` or `audio`. */
	kind: TrackKind,
	/**  Display name; defaults to `V<n>` / `A<n>`. */
	name?: string | null,
	/**  Display position, 0 = top (clamped to the end). */
	index?: number | null,
};

/**  Result of `track.add`. */
export type TrackAddOutput = {
	/**  The new track. */
	track: TrackId,
};

/**
 *  The ID of a `Track`: `trk_…`.
 * 
 *  Serialized as a string, exported to TypeScript as `string`.
 */
export type TrackId = string & { readonly __brand: "TrackId" };

/**
 *  What a track holds. Schema v1 edits only video and audio tracks; the other kinds exist so
 *  documents and commands can name them (ops answer `Unsupported`).
 */
export type TrackKind = 
/**  Picture layers. */
"video" | 
/**  Sound. */
"audio" | 
/**  Titles (later versions). */
"text" | 
/**  Captions (later versions). */
"caption" | 
/**  Adjustment layers (later versions). */
"adjustment";

/**
 *  Removes a track together with its items. Fails with `Locked` if the track is locked, or
 *  if a linked partner that would be left alone in its group is on a locked track. Linked
 *  partners of the removed items stay; a partner left alone in its group is unlinked.
 */
export type TrackRemove = {
	/**  The track. */
	track: TrackId,
};

/**  Result of `track.remove`. */
export type TrackRemoveOutput = {
	/**  The removed track. */
	track: TrackId,
	/**  How many items it held (removed with it). */
	removed_items: number,
};

/**
 *  Changes track properties; absent fields keep their value. Works on locked tracks (that is
 *  how a track is unlocked).
 */
export type TrackSet = {
	/**  The track. */
	track: TrackId,
	/**  New display name. */
	name?: string | null,
	/**  Silence the track. */
	muted?: boolean | null,
	/**  Hide the track from the render. */
	hidden?: boolean | null,
	/**  Lock the track: commands that change its items fail with `Locked`. */
	locked?: boolean | null,
	/**  Solo the track. */
	solo?: boolean | null,
	/**  Track gain in dB, `-144..=48`. */
	gain?: number | null,
};

/**  Result of `track.set`: the track's properties now in effect. */
export type TrackSetOutput = {
	/**  The track. */
	track: TrackId,
	/**  Display name. */
	name: string,
	/**  Silenced. */
	muted: boolean,
	/**  Not rendered. */
	hidden: boolean,
	/**  Item edits fail with `Locked`. */
	locked: boolean,
	/**  Solo. */
	solo: boolean,
	/**  Gain in dB. */
	gain: number | null,
};

/**  One track (depth 1 and 2). */
export type TrackSummary = {
	/**  The track. */
	id: TrackId,
	/**  What it holds. */
	kind: TrackKind,
	/**  Display name. */
	name: string,
	/**  Silenced. */
	muted: boolean,
	/**  Not rendered. */
	hidden: boolean,
	/**  Item edits fail with `Locked`. */
	locked: boolean,
	/**  Solo. */
	solo: boolean,
	/**  Gain in dB. */
	gain: number | null,
	/**  Number of items. */
	item_count: number,
	/**  End of its last item. */
	end: Time,
	/**  The items in start order (depth 2 only). */
	items?: ItemSummary[] | null,
};

/**
 *  Transfer characteristics (H.273).
 * 
 *  Serialized as its name (e.g. `"bt709"`); unknown names are kept as `Other`.
 */
export type TransferCharacteristics = string;

/**
 *  Where and how a visual item is placed on the sequence canvas.
 * 
 *  Coordinates are resolution-independent: `position` is the offset of the item's anchor from
 *  the canvas center in canvas units (1.0 = the canvas width horizontally and the canvas height
 *  vertically; +y is down); `anchor` is a point of the item in item units ((0, 0) top-left,
 *  (0.5, 0.5) center); `scale` multiplies the aspect-fit size; `rotation` is in degrees,
 *  clockwise.
 */
export type Transform = {
	/**  Offset of the anchor from the canvas center, in canvas units. */
	position: Vec2,
	/**  Size multiplier per axis (1.0 = aspect-fit). */
	scale: Vec2,
	/**  Clockwise rotation in degrees. */
	rotation: number,
	/**  The item point that `position` places and rotation turns around, in item units. */
	anchor: Vec2,
} & { [key in string]: unknown };

/**  A partial transform: absent fields keep their value. */
export type TransformPatch = {
	/**  Offset of the anchor from the canvas center, in canvas units (+y is down). */
	position: Vec2 | null,
	/**  Size multiplier per axis (1.0 = aspect-fit); finite and `>= 0`. */
	scale: Vec2 | null,
	/**  Clockwise rotation in degrees. */
	rotation: number | null,
	/**  The item point `position` places and rotation turns around, in item units. */
	anchor: Vec2 | null,
};

/**  Which edge of a clip to trim. */
export type TrimEdge = 
/**  The first frame (changes `start`, `source_in` and the length). */
"start" | 
/**  The last frame (changes the length). */
"end";

/**  A clip after trimming. */
export type TrimmedClip = {
	/**  The clip. */
	item: ItemId,
	/**  Its start. */
	start: Time,
	/**  Its length. */
	duration: Duration,
	/**  Its source position. */
	source_in: Time,
};

/**
 *  `tx.opened` / `tx.locked`: an open transaction and the items it soft-locks (WP-1B.09), for
 *  "agent is editing" indicators. `tx.opened` comes when it opens (no items yet); `tx.locked`
 *  each time a gesture or proposal locks more items, after the `doc.patched` that touched them.
 *  After `Lagged`, re-read `edit.locks`.
 */
export type TxActivity = {
	/**  The transaction. */
	tx_id: TxId,
	/**  `batch`, `gesture` or `proposal`. */
	kind: TxKind,
	/**  Its label. */
	label: string,
	/**  Who opened it. */
	actor: Actor,
	/**  Every item it soft-locks so far, in id order (never any for a batch). */
	items: ItemId[],
	/**  The live revision. */
	rev: Rev,
};

/**  A cancelled transaction. */
export type TxCancelled = {
	/**  Its id. */
	tx: TxId,
	/**  Its kind. */
	kind: TxKind,
	/**  The live revision afterwards. */
	rev: Rev,
};

/**  A committed transaction. */
export type TxCommitted = {
	/**  Its id. */
	tx: TxId,
	/**  Its kind. */
	kind: TxKind,
	/**  Whether it changed the document (and made an undo entry). */
	changed: boolean,
	/**  The live revision afterwards. */
	rev: Rev,
	/**  The committed revision afterwards. */
	committed_rev: Rev,
};

/**
 *  `tx.closed`: an open transaction ended and released its soft locks (WP-1B.09). Comes after
 *  the `doc.patched` of its commit or rollback.
 */
export type TxEnded = {
	/**  The transaction. */
	tx_id: TxId,
	/**  `batch`, `gesture` or `proposal`. */
	kind: TxKind,
	/**  Who opened it. */
	actor: Actor,
	/**
	 *  Committed, cancelled, rolled back (connection closed), expired (idle gesture) or
	 *  conflicted (discarded after another commit overlapped it).
	 */
	outcome: TxOutcome,
	/**  The items it no longer locks, in id order. */
	items: ItemId[],
	/**  The live revision afterwards. */
	rev: Rev,
	/**  The committed revision afterwards. */
	committed_rev: Rev,
};

/**
 *  A transaction: an implicit single-command one, or an open batch, gesture or proposal.
 * 
 *  Allocated by the document actor in increasing order; `tx_<n>` on the wire.
 */
export type TxId = string & { readonly __brand: "TxId" };

/**  What kind of open transaction (arch §5.2, ADR-0017). */
export type TxKind = 
/**
 *  A batch (`edit.begin_tx` / `edit.commit_tx`): its changes become visible only when it
 *  commits.
 */
"batch" | 
/**
 *  A continuous gesture (dragging, scrubbing a slider): updates the document live, collapses
 *  into one undo step on commit, rolls back on cancel, auto-cancels after
 *  [`GESTURE_IDLE_TIMEOUT`](crate::GESTURE_IDLE_TIMEOUT) without a request naming it.
 */
"gesture" | 
/**  A copilot proposal (arch §14b): live like a gesture, no idle timeout. */
"proposal";

/**  An open transaction and the items it soft-locks, as `edit.locks` reports it. */
export type TxLocks = {
	/**  The transaction. */
	tx: TxId,
	/**  `batch`, `gesture` or `proposal`. */
	kind: TxKind,
	/**  Its label (the undo entry's name). */
	label: string,
	/**  Who opened it. */
	actor: Actor,
	/**  Whether the caller's connection owns it. */
	mine: boolean,
	/**
	 *  The items it soft-locks, in id order. Only gestures and proposals lock; a batch's
	 *  changes are invisible until it commits, so it locks nothing.
	 */
	items: ItemId[],
	/**  When it was opened. */
	opened_at: WallTime,
	/**  When a request last named it. */
	last_activity: WallTime,
	/**
	 *  A gesture's idle deadline: the engine cancels it then unless a request names it first.
	 *  `null` for proposals and batches (no idle timeout).
	 */
	expires_at: WallTime | null,
	/**  A commit by another transaction overlapped its changes: it can only be cancelled. */
	conflicted: boolean,
};

/**  An opened transaction. */
export type TxOpened = {
	/**  Its id (pass it as `_meta.tx`). */
	tx: TxId,
	/**  Its kind. */
	kind: TxKind,
	/**  Its label. */
	label: string,
	/**  The live revision it was opened at. */
	rev: Rev,
};

/**  How an open transaction ended. */
export type TxOutcome = 
/**  Committed by its owner. */
"committed" | 
/**  Cancelled by its owner. */
"cancelled" | 
/**  Rolled back by the engine (its connection closed, WP-1B.09). */
"rolled_back" | 
/**  Rolled back by the engine: a gesture idle for [`GESTURE_IDLE_TIMEOUT`](crate::GESTURE_IDLE_TIMEOUT). */
"expired" | 
/**
 *  Discarded when its owner tried to commit it: a commit by another transaction had
 *  overlapped its changes first, so it could only be cancelled (it showed no live changes
 *  since then).
 */
"conflicted";

/**  The UI view state of a project (arch §5.1). Persisted in `.cutweave/ui-state.json`. */
export type UiState = {
	/**  Playhead position on the timeline, `>= 0`. */
	playhead: Time,
	/**  Timeline zoom in pixels per second. */
	zoom: number | null,
	/**  Timeline scroll offset. */
	scroll: Scroll,
	/**
	 *  Selected entities, in selection order, without duplicates. Every ID existed when it was
	 *  selected; IDs that no longer exist are dropped.
	 */
	selection: SelectionRef[],
	/**  Dock/panel layout. Opaque to the engine (owned by the UI); `null` until the UI sets it. */
	panel_layout: unknown,
	/**  Preview resolution. */
	preview_quality: PreviewQuality,
	/**  Master output gain (linear, `0..=4`, 1 = unity). */
	master_gain: number | null,
};

/**
 *  Undoes the latest change of an actor (default: yours) as a new transaction. History is per
 *  actor: undoing the agent's change leaves your later edits alone. Refused with
 *  `Conflict{reason: history_target_modified}` when someone changed the same things since (the
 *  detail names them) or the result would be invalid; nothing changes then.
 */
export type Undo = {
	/**
	 *  Whose change: `user`, `agent:<label>`, `plugin:<id>`, `system`, or `*` for the most
	 *  recent change by anyone. Default: the caller's own.
	 */
	actor?: HistoryScope | null,
};

/**  A 2D vector (positions, scales, anchors). */
export type Vec2 = {
	/**  Horizontal component. */
	x: number,
	/**  Vertical component (down is positive). */
	y: number,
};

/**
 *  Returns the current view state: playhead, zoom, scroll, selection, panel layout, preview
 *  quality and master gain.
 */
export type ViewGet = Record<string, never>;

/**
 *  A partial update of [`UiState`]: fields that are present replace the current value, absent
 *  fields are left alone (JSON `null` counts as absent, so `panel_layout` is reset with `{}`).
 */
export type ViewPatch = {
	/**  New playhead (flicks, seconds text; `>= 0`). */
	playhead?: TimeInput | null,
	/**  New zoom in pixels per second. */
	zoom?: number | null,
	/**  New scroll offset. */
	scroll?: Scroll | null,
	/**  New selection (replaces the whole selection; every ID must exist). */
	selection?: SelectionRef[] | null,
	/**  New panel layout (opaque JSON, replaces the whole value). */
	panel_layout?: unknown | null,
	/**  New preview resolution. */
	preview_quality?: PreviewQuality | null,
	/**  New master gain (linear, `0..=4`). */
	master_gain?: number | null,
};

/**  Changes the selection. Every ID that is added must exist in the project. */
export type ViewSelect = {
	/**  The entities to act on. */
	ids: SelectionRef[],
	/**  How to combine them with the current selection (default `replace`). */
	mode?: SelectMode | null,
};

/**
 *  Merges a partial update into the view state: present fields replace the current value,
 *  absent ones are kept. Nothing is applied if any field is invalid. Not undoable; never
 *  changes the document.
 */
export type ViewSet = {
	/**  The fields to change. */
	patch: ViewPatch,
};

/**  Moves the playhead. */
export type ViewSetPlayhead = {
	/**  New playhead, in flicks or seconds text; `>= 0`. */
	at: TimeInput,
};

/**  Sets the timeline zoom. */
export type ViewSetZoom = {
	/**  Pixels per second, `0.001..=100000`. */
	zoom: number | null,
};

/**  Visual properties of an item (arch §4.2 `VisualProps`, v1 subset). */
export type VisualProps = {
	/**  Placement on the canvas. */
	transform: Transform,
	/**  Opacity, 0.0 (transparent) to 1.0 (opaque). */
	opacity: number,
} & { [key in string]: unknown };

/**  A wall-clock instant: milliseconds since the Unix epoch. */
export type WallTime = number;
